/**
 * CanvasRoute — the /workflows/canvas content area (#1314, P2 F-Task 1;
 * lifecycle entry wired in F-Task 6).
 *
 * Renders the three-region CanvasEditor (palette / React Flow / config
 * panel plus the lifecycle toolbar) for the workflow identified by the
 * `?workflowId=` query param. `onWorkflowChange` (passed down into
 * `CanvasEditor`'s toolbar) updates that query param via `setSearchParams`
 * so New/Open drive the URL rather than component-local state — reloading
 * the page keeps the same workflow open.
 *
 * A missing workflowId renders a neutral empty state with its own "New"
 * action (createWorkflow -> set ?workflowId=) so a first-time visitor has
 * an obvious way in, without the CanvasEditor's three-region grid awkwardly
 * rendering an empty ReactFlow canvas before any workflow exists.
 *
 * #1357 AC 2: the open workflow's name becomes the browser tab title. The
 * title is SHARED state — workflow-mfe runs inside the shell, which owns the
 * document — so the effect captures whatever title it found and restores it on
 * unmount. Without the restore, navigating from the canvas to any other
 * vertical would leave that workflow's name in the tab indefinitely.
 *
 * P3 Task 3: CanvasEditor mounts its own `Toast.Provider`/`Toast.Viewport`
 * (see that module's doc-comment) — neither workflow-mfe nor platform-chrome
 * mounts a shared one, and CanvasEditor is also rendered directly (without
 * this route) in its own test suite, so the provider has to travel with it
 * rather than living here.
 */

import { type ReactElement, useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { CanvasEditor } from "../canvas/CanvasEditor";
import { createWorkflow, useWorkflow } from "../api/workflows";

const BUTTON_CLASSES =
  "flex h-cog-9 items-center justify-center rounded-md border border-cog-divider bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-blue-600";

export default function CanvasRoute(): ReactElement {
  const [searchParams, setSearchParams] = useSearchParams();
  const workflowId = searchParams.get("workflowId") ?? "";
  const [isCreating, setIsCreating] = useState(false);

  // #1357 AC 2 — the workflow's name in the browser tab.
  const workflowLoad = useWorkflow(workflowId);
  const openWorkflowName =
    workflowLoad.state === "data" ? workflowLoad.workflow.name : "";

  useEffect(() => {
    if (openWorkflowName === "") return;
    const previousTitle = document.title;
    document.title = openWorkflowName;
    return () => {
      // The shell owns the document title, so put back exactly what was there
      // rather than assuming a default — leaving a stale workflow name in the
      // tab after navigating away is the failure this guards.
      document.title = previousTitle;
    };
  }, [openWorkflowName]);

  const handleWorkflowChange = (nextWorkflowId: string): void => {
    const next = new URLSearchParams(searchParams);
    next.set("workflowId", nextWorkflowId);
    setSearchParams(next);
  };

  const handleNew = (): void => {
    if (isCreating) return;
    setIsCreating(true);
    createWorkflow(m.workflow_toolbar_name_placeholder(), "")
      .then((workflow) => {
        setIsCreating(false);
        handleWorkflowChange(workflow.id);
      })
      .catch(() => setIsCreating(false));
  };

  if (workflowId === "") {
    return (
      <section
        className="flex flex-1 flex-col items-center justify-center gap-cog-2 px-cog-5 py-cog-9 text-center"
        aria-labelledby="workflow-canvas-empty-heading"
      >
        <h2
          id="workflow-canvas-empty-heading"
          className="text-heading-lg text-cog-text-primary"
        >
          {m.workflow_canvas_empty_title()}
        </h2>
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_canvas_empty_subtitle()}
        </p>
        <button type="button" onClick={handleNew} className={BUTTON_CLASSES}>
          {m.workflow_toolbar_new()}
        </button>
      </section>
    );
  }

  return (
    <div className="flex min-h-cog-0 flex-1">
      <CanvasEditor workflowId={workflowId} onWorkflowChange={handleWorkflowChange} />
    </div>
  );
}


