/**
 * ProjectDetailRoute — /workflows/projects/:projectId (#1353).
 *
 * Lists the workflows inside one project with name, description, last-saved
 * time and run status, filterable by tag (#1356 step 3), with delete behind a
 * confirm.
 *
 * The tag filter is applied SERVER-SIDE (`?tag=`), not by filtering the array
 * this component holds. The list is paged, so a client-side filter would only
 * ever narrow the current page and would silently hide matches beyond it —
 * which looks identical to "no more matches" and is the kind of bug nobody
 * reports because the UI seems to be working.
 *
 * The filter also lives in the URL as `?tag=`, so a filtered view is
 * linkable and survives a reload. That is what makes "I'm looking at the
 * release workflows" something you can send to someone.
 *
 * Write affordances (delete a workflow, open Settings) render only when
 * `canWriteProject` says the caller may. The server refuses regardless — this
 * only keeps a doomed button off the screen.
 */

import { type ReactElement, useCallback, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { Button } from "@omnicore-platform/ui";
import { ChevronLeft } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import {
  canWriteProject,
  useProject,
  useProjectWorkflows,
  type ProjectWorkflow,
} from "../api/projects";
import { deleteWorkflow } from "../api/workflows";
import { useTags } from "../api/tags";
import { ProjectWorkflowRow } from "../projects/ProjectWorkflowRow";
import { TagFilterBar } from "../projects/TagFilterBar";
import { DeleteWorkflowDialog } from "../canvas/DeleteWorkflowDialog";

export default function ProjectDetailRoute(): ReactElement {
  const { projectId = "" } = useParams<{ projectId: string }>();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const activeTag = searchParams.get("tag") ?? "";

  const { project, isLoading: projectLoading, error: projectError } =
    useProject(projectId);
  const {
    workflows,
    isLoading: workflowsLoading,
    error: workflowsError,
    refetch,
  } = useProjectWorkflows(projectId, activeTag);
  const { tags } = useTags();

  const [pendingDelete, setPendingDelete] = useState<ProjectWorkflow | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleTagChange = useCallback(
    (tag: string) => {
      // `replace` so filtering does not stack history entries — Back should
      // leave the project, not step through every chip the reader tried.
      setSearchParams(tag ? { tag } : {}, { replace: true });
    },
    [setSearchParams],
  );

  const handleConfirmDelete = useCallback(async () => {
    if (pendingDelete === null) return;
    setIsDeleting(true);
    try {
      await deleteWorkflow(pendingDelete.id);
      setPendingDelete(null);
      refetch();
    } finally {
      setIsDeleting(false);
    }
  }, [pendingDelete, refetch]);

  if (projectLoading) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_detail_loading()}
        </p>
      </section>
    );
  }

  if (projectError !== null || project === null) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {projectError ?? m.workflow_project_detail_not_found()}
        </p>
      </section>
    );
  }

  const mayWrite = canWriteProject(project);

  return (
    <section className="flex flex-1 flex-col gap-cog-4 px-cog-5 py-cog-5">
      <header className="flex flex-wrap items-start justify-between gap-cog-3">
        <div className="flex flex-col gap-cog-1">
          {/* A button, not a link, by request. The visible label is the
              destination ("Projects") with a leading chevron for direction;
              the accessible name stays the full "Back to projects" via
              aria-label, since "Projects, button" alone is ambiguous read out
              of context. Absolute path rather than `to=".."` because this
              also has to work from the settings child route. */}
          <Button
            variant="secondary"
            size="sm"
            onClick={() => navigate("/workflows/projects")}
            aria-label={m.workflow_project_detail_back()}
            className="self-start"
          >
            <ChevronLeft aria-hidden="true" className="h-cog-4 w-cog-4" />
            {m.workflow_project_detail_back_label()}
          </Button>
          <h2 className="text-heading-md font-semibold text-cog-text-primary">
            {project.name}
          </h2>
          {project.description.trim() !== "" ? (
            <p className="text-body-sm text-cog-text-secondary">
              {project.description}
            </p>
          ) : null}
        </div>

        {mayWrite ? (
          <Link
            to="settings"
            className="
              rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm
              text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          >
            {m.workflow_project_detail_settings()}
          </Link>
        ) : null}
      </header>

      <TagFilterBar tags={tags} value={activeTag} onChange={handleTagChange} />

      {workflowsLoading ? (
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_detail_loading_workflows()}
        </p>
      ) : workflowsError !== null ? (
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {workflowsError}
        </p>
      ) : workflows.length === 0 ? (
        // Two distinct empty states: an empty project prompts you to add a
        // workflow, while an over-filtered list prompts you to clear the
        // filter. Collapsing them would tell someone their project is empty
        // when it is not.
        <p className="text-body-md text-cog-text-secondary">
          {activeTag !== ""
            ? m.workflow_project_detail_empty_for_tag({ tag: activeTag })
            : m.workflow_project_detail_empty()}
        </p>
      ) : (
        <ul className="flex flex-col">
          {workflows.map((wf) => (
            <ProjectWorkflowRow
              key={wf.id}
              workflow={wf}
              // `workflowId`, not `workflow`: CanvasRoute reads
              // searchParams.get("workflowId"), and an unknown key silently
              // opens an empty canvas rather than erroring.
              href={`/workflows/canvas?workflowId=${encodeURIComponent(wf.id)}`}
              onDelete={mayWrite ? setPendingDelete : undefined}
            />
          ))}
        </ul>
      )}

      {pendingDelete !== null ? (
        <DeleteWorkflowDialog
          workflowName={pendingDelete.name}
          isPending={isDeleting}
          onConfirm={() => void handleConfirmDelete()}
          onCancel={() => setPendingDelete(null)}
        />
      ) : null}
    </section>
  );
}


--- frontends/workflow-mfe/src/routes/ProjectSettingsRoute.tsx (292 lines) ---
/**
 * ProjectSettingsRoute — /workflows/projects/:projectId/settings (#1354),
 * which also hosts sharing (#1355).
 *
 * Edit name and description, share the project, or delete it. Sharing is
 * an inline section rather than a modal: it is a setting like the others,
 * and a dialog made a routine grant cost an open and a dismiss.
 *
 * Save is an explicit button, NOT the per-keystroke PATCH CanvasToolbar uses
 * for a workflow's name. The difference is intentional: the toolbar is editing
 * the thing already open in front of you and an autosave there is invisible
 * and welcome, whereas this is a settings form whose delete button sits a few
 * pixels away. A form you can half-type into and navigate away from without
 * committing is the safer shape here.
 *
 * The whole route is behind `canWriteProject`. A caller with no write standing
 * gets an explanation rather than a form that will 403 on submit — and the
 * server refuses regardless, so this is an affordance, not the enforcement.
 */

import { type ReactElement, useCallback, useEffect, useId, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Button } from "@omnicore-platform/ui";
import { ChevronLeft } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import {
  canWriteProject,
  deleteProject,
  updateProject,
  useProject,
} from "../api/projects";
import { DeleteProjectDialog } from "../projects/DeleteProjectDialog";
import { ShareProjectPanel } from "../projects/ShareProjectPanel";

export default function ProjectSettingsRoute(): ReactElement {
  const { projectId = "" } = useParams<{ projectId: string }>();
  const navigate = useNavigate();
  const { project, isLoading, error, refetch } = useProject(projectId);

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const nameId = useId();
  const descriptionId = useId();

  // Seed the form once the project arrives, and re-seed if the route swaps to
  // a different project without unmounting.
  useEffect(() => {
    if (project === null) return;
    setName(project.name);
    setDescription(project.description);
  }, [project]);

  const handleSave = useCallback(async () => {
    if (project === null) return;
    setIsSaving(true);
    setSaved(false);
    try {
      await updateProject(project.id, { name, description });
      setSaveError(null);
      setSaved(true);
      // Re-read so the header above reflects the change immediately
      // (#1354 step 3) instead of showing the pre-save name until a reload.
      refetch();
    } catch (err: unknown) {
      setSaveError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setIsSaving(false);
    }
  }, [description, name, project, refetch]);

  const handleDelete = useCallback(async () => {
    if (project === null) return;
    setIsDeleting(true);
    try {
      await deleteProject(project.id);
      // The project no longer exists, so returning to its detail route would
      // render a not-found. Go to the list.
      navigate("/workflows/projects", { replace: true });
    } catch (err: unknown) {
      setDeleteError(err instanceof Error ? err.message : "Unknown error");
      setIsDeleting(false);
    }
  }, [navigate, project]);

  if (isLoading) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_settings_loading()}
        </p>
      </section>
    );
  }

  if (error !== null || project === null) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {error ?? m.workflow_project_detail_not_found()}
        </p>
      </section>
    );
  }

  if (!canWriteProject(project)) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_settings_read_only()}
        </p>
      </section>
    );
  }

  const nameIsEmpty = name.trim() === "";

  return (
    <section className="flex flex-1 flex-col gap-cog-5 px-cog-5 py-cog-5">
      <header className="flex flex-col items-start gap-cog-1">
        {/* Settings had no way out but the nav tab, which drops you on the
            projects LIST rather than the project you were configuring. This
            returns to the project itself. Visible label is the project name;
            the accessible name spells out the direction. */}
        <Button
          variant="secondary"
          size="sm"
          onClick={() => navigate(`/workflows/projects/${project.id}`)}
          aria-label={m.workflow_project_settings_back({ name: project.name })}
        >
          <ChevronLeft aria-hidden="true" className="h-cog-4 w-cog-4" />
          {project.name}
        </Button>
        <h2 className="text-heading-md font-semibold text-cog-text-primary">
          {m.workflow_project_settings_title({ name: project.name })}
        </h2>
      </header>

      <form
        className="flex max-w-xl flex-col gap-cog-4"
        onSubmit={(event) => {
          event.preventDefault();
          if (!nameIsEmpty) void handleSave();
        }}
      >
        <div className="flex flex-col gap-cog-1">
          <label
            htmlFor={nameId}
            className="text-body-sm font-medium text-cog-text-primary"
          >
            {m.workflow_project_settings_name_label()}
          </label>
          <input
            id={nameId}
            type="text"
            value={name}
            maxLength={255}
            aria-invalid={nameIsEmpty}
            onChange={(event) => {
              setName(event.target.value);
              setSaved(false);
            }}
            className="
              rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2
              text-body-sm text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          />
          {nameIsEmpty ? (
            <p
              role="alert"
              className="text-body-sm text-cog-danger-700 dark:text-cog-danger-dark"
            >
              {m.workflow_project_settings_name_required()}
            </p>
          ) : null}
        </div>

        <div className="flex flex-col gap-cog-1">
          <label
            htmlFor={descriptionId}
            className="text-body-sm font-medium text-cog-text-primary"
          >
            {m.workflow_project_settings_description_label()}
          </label>
          <textarea
            id={descriptionId}
            value={description}
            rows={3}
            onChange={(event) => {
              setDescription(event.target.value);
              setSaved(false);
            }}
            className="
              rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2
              text-body-sm text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          />
        </div>

        {saveError !== null ? (
          <p
            role="alert"
            className="text-body-sm text-cog-danger-700 dark:text-cog-danger-dark"
          >
            {saveError}
          </p>
        ) : null}

        {/* role="status", not "alert": a successful save is not an
            interruption, and an assertive announcement on every save would
            talk over a screen-reader user mid-sentence. */}
        {saved ? (
          <p role="status" className="text-body-sm text-cog-text-secondary">
            {m.workflow_project_settings_saved()}
          </p>
        ) : null}

        <div className="flex flex-wrap gap-cog-3">
          <button
            type="submit"
            disabled={isSaving || nameIsEmpty}
            aria-busy={isSaving}
            className="
              rounded-md bg-cog-blue-600 px-cog-4 py-cog-2 text-body-sm font-medium text-white
              disabled:cursor-not-allowed disabled:border-cog-border disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary disabled:opacity-50
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          >
            {m.workflow_project_settings_save()}
          </button>
        </div>
      </form>

      {/* Sharing is a setting, so it renders here rather than behind a modal
          the owner has to open and dismiss. It owns its own reads and writes;
          nothing above needs to know a grant changed. */}
      <ShareProjectPanel projectId={project.id} projectName={project.name} />

      {/* Danger zone, visually separated so Delete is never adjacent to Save. */}
      <div className="mt-cog-4 flex max-w-xl flex-col gap-cog-2 rounded-lg border border-cog-danger-200 p-cog-4 dark:border-cog-danger-dark">
        <h3 className="text-body-md font-semibold text-cog-text-primary">
          {m.workflow_project_settings_danger_heading()}
        </h3>
        <p className="text-body-sm text-cog-text-secondary">
          {m.workflow_project_settings_danger_body({
            count: project.workflowCount,
          })}
        </p>
        <div>
          {/* Solid danger, not an outline: it is the entry to an irreversible
              cascade and should read the same as every other destructive
              action on these screens. */}
          <Button
            variant="danger"
            size="sm"
            onClick={() => setIsConfirmingDelete(true)}
          >
            {m.workflow_project_settings_delete()}
          </Button>
        </div>
      </div>

      {isConfirmingDelete ? (
        <DeleteProjectDialog
          projectName={project.name}
          workflowCount={project.workflowCount}
          isPending={isDeleting}
          error={deleteError}
          onConfirm={() => void handleDelete()}
          onCancel={() => {
            setIsConfirmingDelete(false);
            setDeleteError(null);
          }}
        />
      ) : null}
    </section>
  );
}


