/**
 * ProjectDetailRoute — /workflows/projects/:projectId (#1353).
 *
 * Lists the workflows inside one project with name, description, last-saved
 * time and run status, filterable by tag (#1356 step 3), with delete behind a
 * confirm.
 *
 * The tag filter is applied SERVER-SIDE (`?tag=`), not by filtering the array
 * this component holds. The list is paged, so a client-side filter would only
 * ever narrow the current page and would silently hide matches beyond it —
 * which looks identical to "no more matches" and is the kind of bug nobody
 * reports because the UI seems to be working.
 *
 * The filter also lives in the URL as `?tag=`, so a filtered view is
 * linkable and survives a reload. That is what makes "I'm looking at the
 * release workflows" something you can send to someone.
 *
 * Write affordances (delete a workflow, open Settings) render only when
 * `canWriteProject` says the caller may. The server refuses regardless — this
 * only keeps a doomed button off the screen.
 */

import { type ReactElement, useCallback, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { Button } from "@omnicore-platform/ui";
import { ChevronLeft } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import {
  canWriteProject,
  useProject,
  useProjectWorkflows,
  type ProjectWorkflow,
} from "../api/projects";
import { deleteWorkflow } from "../api/workflows";
import { useTags } from "../api/tags";
import { ProjectWorkflowRow } from "../projects/ProjectWorkflowRow";
import { TagFilterBar } from "../projects/TagFilterBar";
import { DeleteWorkflowDialog } from "../canvas/DeleteWorkflowDialog";

export default function ProjectDetailRoute(): ReactElement {
  const { projectId = "" } = useParams<{ projectId: string }>();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const activeTag = searchParams.get("tag") ?? "";

  const { project, isLoading: projectLoading, error: projectError } =
    useProject(projectId);
  const {
    workflows,
    isLoading: workflowsLoading,
    error: workflowsError,
    refetch,
  } = useProjectWorkflows(projectId, activeTag);
  const { tags } = useTags();

  const [pendingDelete, setPendingDelete] = useState<ProjectWorkflow | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleTagChange = useCallback(
    (tag: string) => {
      // `replace` so filtering does not stack history entries — Back should
      // leave the project, not step through every chip the reader tried.
      setSearchParams(tag ? { tag } : {}, { replace: true });
    },
    [setSearchParams],
  );

  const handleConfirmDelete = useCallback(async () => {
    if (pendingDelete === null) return;
    setIsDeleting(true);
    try {
      await deleteWorkflow(pendingDelete.id);
      setPendingDelete(null);
      refetch();
    } finally {
      setIsDeleting(false);
    }
  }, [pendingDelete, refetch]);

  if (projectLoading) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_detail_loading()}
        </p>
      </section>
    );
  }

  if (projectError !== null || project === null) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {projectError ?? m.workflow_project_detail_not_found()}
        </p>
      </section>
    );
  }

  const mayWrite = canWriteProject(project);

  return (
    <section className="flex flex-1 flex-col gap-cog-4 px-cog-5 py-cog-5">
      <header className="flex flex-wrap items-start justify-between gap-cog-3">
        <div className="flex flex-col gap-cog-1">
          {/* A button, not a link, by request. The visible label is the
              destination ("Projects") with a leading chevron for direction;
              the accessible name stays the full "Back to projects" via
              aria-label, since "Projects, button" alone is ambiguous read out
              of context. Absolute path rather than `to=".."` because this
              also has to work from the settings child route. */}
          <Button
            variant="secondary"
            size="sm"
            onClick={() => navigate("/workflows/projects")}
            aria-label={m.workflow_project_detail_back()}
            className="self-start"
          >
            <ChevronLeft aria-hidden="true" className="h-cog-4 w-cog-4" />
            {m.workflow_project_detail_back_label()}
          </Button>
          <h2 className="text-heading-md font-semibold text-cog-text-primary">
            {project.name}
          </h2>
          {project.description.trim() !== "" ? (
            <p className="text-body-sm text-cog-text-secondary">
              {project.description}
            </p>
          ) : null}
        </div>

        {mayWrite ? (
          <Link
            to="settings"
            className="
              rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm
              text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          >
            {m.workflow_project_detail_settings()}
          </Link>
        ) : null}
      </header>

      <TagFilterBar tags={tags} value={activeTag} onChange={handleTagChange} />

      {workflowsLoading ? (
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_project_detail_loading_workflows()}
        </p>
      ) : workflowsError !== null ? (
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {workflowsError}
        </p>
      ) : workflows.length === 0 ? (
        // Two distinct empty states: an empty project prompts you to add a
        // workflow, while an over-filtered list prompts you to clear the
        // filter. Collapsing them would tell someone their project is empty
        // when it is not.
        <p className="text-body-md text-cog-text-secondary">
          {activeTag !== ""
            ? m.workflow_project_detail_empty_for_tag({ tag: activeTag })
            : m.workflow_project_detail_empty()}
        </p>
      ) : (
        <ul className="flex flex-col">
          {workflows.map((wf) => (
            <ProjectWorkflowRow
              key={wf.id}
              workflow={wf}
              // `workflowId`, not `workflow`: CanvasRoute reads
              // searchParams.get("workflowId"), and an unknown key silently
              // opens an empty canvas rather than erroring.
              href={`/workflows/canvas?workflowId=${encodeURIComponent(wf.id)}`}
              onDelete={mayWrite ? setPendingDelete : undefined}
            />
          ))}
        </ul>
      )}

      {pendingDelete !== null ? (
        <DeleteWorkflowDialog
          workflowName={pendingDelete.name}
          isPending={isDeleting}
          onConfirm={() => void handleConfirmDelete()}
          onCancel={() => setPendingDelete(null)}
        />
      ) : null}
    </section>
  );
}


