/**
 * ProjectsRoute — the /workflows/projects list and overview (#1352).
 *
 * Renders every project in the org as a card carrying its name, description
 * and workflow count, plus a New Project button that opens
 * {@link NewProjectDialog}. The whole page is driven by `useProjects`; the
 * workflow count arrives on the project DTO itself
 * (services/workflow-bff/internal/handlers/project.go), so the list costs one
 * request no matter how many projects the org has.
 *
 * Ordering is the server's, not this component's: `project_list`
 * (services/workflow-svc/.../repo/project_repo.py) orders by `LOWER(name)`
 * ascending, so the grid is alphabetical and stable between visits rather
 * than reshuffling whenever anyone touches a workflow. Re-sorting here would
 * mask a server-side ordering regression instead of failing the test that
 * covers it.
 *
 * The four page states are mutually exclusive and checked in this order:
 * loading, error, empty, list. A failed fetch is a distinct `role="alert"`
 * state rather than falling through to the empty state — "you have no
 * projects" and "we could not load your projects" prompt completely different
 * user actions, and conflating them was called out in review on PR #1856.
 *
 * NOTE for #1353: this route deliberately does not render the workflows
 * inside each project. Listing a project's workflows is the project-detail
 * surface, and the card here becomes the link into it.
 */

import { type ReactElement, useCallback, useState } from "react";
import { Button } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { useProjects } from "../api/projects";
import { NewProjectDialog } from "../projects/NewProjectDialog";
import { ProjectCard } from "../projects/ProjectCard";

export default function ProjectsRoute(): ReactElement {
  const { projects, isLoading, error, refetch } = useProjects();
  const [isCreating, setIsCreating] = useState(false);

  const openDialog = useCallback(() => setIsCreating(true), []);
  const closeDialog = useCallback(() => setIsCreating(false), []);

  // Refetch rather than splicing the created project into local state: the
  // list is server-ordered alphabetically, so only a re-read puts the new
  // project at its correct letter.
  const handleCreated = useCallback(() => {
    setIsCreating(false);
    refetch();
  }, [refetch]);

  const dialog = isCreating ? (
    <NewProjectDialog onCreated={handleCreated} onCancel={closeDialog} />
  ) : null;

  if (isLoading) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_projects_loading()}
        </p>
      </section>
    );
  }

  if (error !== null) {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p
          role="alert"
          className="text-body-md text-cog-danger-500 dark:text-cog-danger-dark"
        >
          {m.workflow_projects_error_prefix()}: {error}
        </p>
      </section>
    );
  }

  if (projects.length === 0) {
    return (
      <section
        className="flex flex-1 flex-col items-center justify-center gap-cog-3 px-cog-5 py-cog-9 text-center"
        aria-labelledby="workflow-projects-empty-heading"
      >
        <h2
          id="workflow-projects-empty-heading"
          className="text-heading-lg text-cog-text-primary"
        >
          {m.workflow_projects_empty_title()}
        </h2>
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_projects_empty_subtitle()}
        </p>
        {/* The empty state's whole job is to start the user off, so the CTA is
            here rather than only in the header the empty state replaces. */}
        <Button onClick={openDialog}>{m.workflow_projects_new_button()}</Button>
        {dialog}
      </section>
    );
  }

  return (
    <section
      className="flex flex-1 flex-col gap-cog-5 overflow-y-auto px-cog-5 py-cog-6"
      aria-labelledby="workflow-projects-heading"
    >
      <header className="flex items-center justify-between gap-cog-4">
        <h2
          id="workflow-projects-heading"
          className="text-heading-lg text-cog-text-primary"
        >
          {m.workflow_nav_projects()}
        </h2>
        <Button onClick={openDialog}>{m.workflow_projects_new_button()}</Button>
      </header>

      <ul className="grid grid-cols-1 gap-cog-4 sm:grid-cols-2 xl:grid-cols-3">
        {projects.map((project) => (
          <li key={project.id} className="h-full">
            <ProjectCard project={project} />
          </li>
        ))}
      </ul>

      {dialog}
    </section>
  );
}


