/**
 * TemplatesRoute — the /workflows/templates library (Templates epic #1345).
 *
 * Replaces the #1314 placeholder. One `useTemplates()` call fetches the whole
 * merged library (built-ins + the org's own saved templates); the category
 * grouping (#1346), feature chips (#1347) and name search (#1348) are all
 * applied over it by `templates/filter.ts`, so the three compose and search
 * needs no debounce.
 *
 * USE TEMPLATE (#1349) instantiates SERVER-SIDE and then navigates to the
 * canvas route with `?workflowId=<new>`. The alternative — carrying the
 * snapshot to the canvas in memory as an "unsaved" workflow — would fight
 * this vertical's architecture: CanvasEditor loads its topology from the
 * server by workflowId and autosaves, so there is no unsaved-canvas state for
 * it to hold. #1349's "the workflow is marked as unsaved (the template is a
 * copy, not the original)" is satisfied by the copy being a genuinely
 * separate workflow: editing or running it can never write back to the
 * template, and the same template can be used any number of times. Its
 * "no trigger configured" clause holds because a snapshot carries canvas
 * topology only — nothing here writes a trigger row.
 *
 * DELETE refetches rather than splicing the row out locally: the library is
 * two populations merged server-side, and reconstructing that merge in the
 * client would be a second implementation of ordering that has to agree with
 * the first.
 */

import { type ReactElement, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { Tooltip } from "@omnicore-platform/ui";
import {
  deleteTemplate,
  instantiateTemplate,
  useTemplates,
  type Template,
} from "../api/templates";
import {
  EMPTY_FILTER,
  applyFilter,
  availableFeatures,
  toggleFeature,
  type TemplateFilterState,
} from "../templates/filter";
import { errorMessage } from "../templates/errorMessage";
import { TemplateCategorySection } from "../templates/TemplateCategorySection";
import { TemplateFilters } from "../templates/TemplateFilters";

/** Stable identity for the loading/error arms — see the `templates` memo. */
const EMPTY_TEMPLATES: readonly Template[] = [];

export default function TemplatesRoute(): ReactElement {
  const navigate = useNavigate();
  const state = useTemplates();
  const { refetch } = state;

  const [filter, setFilter] = useState<TemplateFilterState>(EMPTY_FILTER);
  // Collapsed sections, by category key. Sections are EXPANDED by default —
  // browsing is the point of this page, unlike NodePalette where a collapsed
  // tree keeps a narrow rail scannable.
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(new Set());
  const [instantiatingId, setInstantiatingId] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);

  // Memoized rather than a bare conditional: the non-data arms would mint a
  // fresh `[]` on every render, which is a new identity and would re-run both
  // memos below each time.
  const templates = useMemo(
    () => (state.state === "data" ? state.templates : EMPTY_TEMPLATES),
    [state],
  );
  const features = useMemo(() => availableFeatures(templates), [templates]);
  const { sections, matchCount } = useMemo(
    () => applyFilter(templates, filter),
    [templates, filter],
  );
  const filterActive = filter.query.trim() !== "" || filter.features.size > 0;

  const handleToggleSection = (category: string): void => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(category)) next.delete(category);
      else next.add(category);
      return next;
    });
  };

  const handleUse = (template: Template): void => {
    if (instantiatingId !== null) return;
    setInstantiatingId(template.id);
    setActionError(null);
    instantiateTemplate(template.id)
      .then((created) => {
        setInstantiatingId(null);
        // RELATIVE ("../canvas"), never "/workflows/canvas". Canvas is this
        // route's sibling under the same layout, so `..` resolves to the
        // mount point in BOTH router frames — the federated splat mount
        // (no basename, pathname still carries "/workflows") and the
        // standalone bootstrap (basename="/workflows", pathname stripped).
        // A hardcoded absolute path is correct in exactly one of them; see
        // WorkflowNavShell's doc-comment for the same trap.
        navigate(`../canvas?workflowId=${encodeURIComponent(created.workflowId)}`);
      })
      .catch((err: unknown) => {
        setInstantiatingId(null);
        setActionError(errorMessage(err, m.workflow_templates_use_error()));
      });
  };

  const handleDelete = (template: Template): void => {
    setActionError(null);
    deleteTemplate(template.id)
      .then(refetch)
      .catch((err: unknown) => {
        setActionError(errorMessage(err, m.workflow_templates_delete_error()));
      });
  };

  if (state.state === "loading") {
    return (
      <section className="flex flex-1 items-center justify-center px-cog-5 py-cog-9">
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_templates_loading()}
        </p>
      </section>
    );
  }

  if (state.state === "error") {
    // A distinct error state, never a fall-through to the empty state: the
    // library is never legitimately empty (built-ins ship with the service),
    // so rendering "no templates" here would be indistinguishable from a
    // real state the user could act on.
    return (
      <section className="flex flex-1 flex-col items-center justify-center gap-cog-3 px-cog-5 py-cog-9 text-center">
        <p
          role="alert"
          className="text-body-md text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {m.workflow_templates_error_prefix()}: {state.message}
        </p>
        <button
          type="button"
          onClick={refetch}
          className="flex h-cog-9 items-center justify-center rounded-md border border-cog-divider bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-blue-600"
        >
          {m.workflow_templates_retry()}
        </button>
      </section>
    );
  }

  return (
    <section
      aria-labelledby="workflow-templates-heading"
      className="flex flex-1 flex-col gap-cog-5 overflow-y-auto px-cog-5 py-cog-6"
    >
      <div className="flex flex-col gap-cog-1">
        <h2
          id="workflow-templates-heading"
          className="text-heading-lg text-cog-text-primary"
        >
          {m.workflow_templates_title()}
        </h2>
        <p className="text-body-md text-cog-text-secondary">
          {m.workflow_templates_subtitle()}
        </p>
      </div>

      <TemplateFilters
        query={filter.query}
        onQueryChange={(query) => setFilter((prev) => ({ ...prev, query }))}
        features={features}
        selectedFeatures={filter.features}
        onToggleFeature={(feature) =>
          setFilter((prev) => ({ ...prev, features: toggleFeature(prev.features, feature) }))
        }
        onClearFeatures={() => setFilter((prev) => ({ ...prev, features: new Set() }))}
      />

      {actionError !== null && (
        <p role="alert" className="text-body-sm text-cog-danger-700 dark:text-cog-danger-dark">
          {actionError}
        </p>
      )}

      {filterActive && matchCount === 0 ? (
        <p
          role="status"
          className="rounded-md border border-dashed border-cog-divider px-cog-4 py-cog-6 text-center text-body-md text-cog-text-secondary"
        >
          {m.workflow_templates_no_results()}
        </p>
      ) : (
        // One provider for the whole page rather than one per card: the cards
        // render a tooltip per feature glyph, and Radix requires a provider
        // above every Tooltip.Root. Owned here for the same reason
        // CanvasToolbar owns its own — the page is the smallest thing that
        // knows how many tooltips it contains.
        <Tooltip.Provider>
          {sections.map((section) => (
            <TemplateCategorySection
              key={section.category}
              section={section}
              expanded={!collapsed.has(section.category)}
              onToggle={handleToggleSection}
              onUse={handleUse}
              onDelete={handleDelete}
              instantiatingId={instantiatingId}
              filterActive={filterActive}
            />
          ))}
        </Tooltip.Provider>
      )}
    </section>
  );
}



